# build.ps1 - assemble the shippable artifacts.
#
#   .\build.ps1                     -> version stamped "dev"
#   .\build.ps1 -Version 0.6-beta   -> version stamped "0.6-beta"
#
# Produces two ready-to-zip trees under dist\, plus the staged payload they share:
#
#   dist\bma-payload\                     the built mod files (intermediate; embedded
#                                         into the installer and mirrored into manual\)
#     BMA_Accessibility.js                bundled from src\*.js, load order matters
#     audio\*.wav                         generated by gen_sounds.js
#     bma_tts.node                        copied from the nw-gyp build, if present
#     Tolk.dll, nvdaControllerClient64.dll   bundled screen-reader bridge, from redist\
#
#   obj\ReadMe.txt                        plain-text readme generated from ReadMe.md;
#                                         build output, never committed
#
#   dist\ship\                            -> the one and only download, zipped whole
#     ReadMe.txt                             (the generated copy above)
#     BlackmoonProphecy-Accessibility-V<version>-Setup.exe
#     Manual install\                        for users who would rather place the files
#       www\js\plugins\BMA_Accessibility.js  themselves; mirrors the game folder layout so
#       www\mod\...                          its contents drop straight into the game root
#
# Run native\build.bat first to produce bma_tts.node (one-time, needs nw-gyp + VS C++).

param([string]$Version = 'dev')

$ErrorActionPreference = 'Stop'
$root    = $PSScriptRoot
$dist    = Join-Path $root 'dist'
$obj     = Join-Path $root 'obj'
$payload = Join-Path $dist 'bma-payload'
$ship    = Join-Path $dist 'ship'
$shipManual = Join-Path $ship 'Manual install'

New-Item -ItemType Directory -Force -Path $payload | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $payload 'audio') | Out-Null
New-Item -ItemType Directory -Force -Path $obj | Out-Null

# --- 1. Bundle JS (Core must be first; Text/Menus/Nav depend on it) ---
$order = @('BMA_Core.js','BMA_Text.js','BMA_Menus.js','BMA_Nav.js')
$bundle = Join-Path $payload 'BMA_Accessibility.js'
$header = @"
//=============================================================================
// BMA_Accessibility.js  -  Blackmoon Prophecy Remake accessibility mod (bundled)
// Generated by build.ps1. Do not edit here; edit src\*.js and rebuild.
//=============================================================================
/*:
 * @plugindesc Blind-accessibility layer: TTS menus/dialogue/battle, spoken
 * pathfinding navigation, and audio cues. Requires Tolk.dll in www\mod\.
 * @author BMA
 */
"@
Set-Content -Path $bundle -Value $header -Encoding utf8
foreach ($f in $order) {
  $p = Join-Path $root (Join-Path 'src' $f)
  if (-not (Test-Path $p)) { throw "Missing source: $p" }
  Add-Content -Path $bundle -Value ("`n// ===== $f =====`n") -Encoding utf8
  Add-Content -Path $bundle -Value (Get-Content $p -Raw) -Encoding utf8
}
Write-Host "Bundled -> $bundle"

# --- 2. Generate sound cues ---
& node (Join-Path $root 'src\gen_sounds.js') (Join-Path $payload 'audio')
if ($LASTEXITCODE -ne 0) { throw "gen_sounds.js failed" }

# --- 3. Copy prebuilt native addon ---
$node = Join-Path $root 'native\bma_tts\build\Release\bma_tts.node'
if (Test-Path $node) {
  Copy-Item $node (Join-Path $payload 'bma_tts.node') -Force
  Write-Host "Copied bma_tts.node"
} else {
  Write-Warning "bma_tts.node not found - run native\build.bat first. Patch will fall back to Web Speech until it's present."
}

# --- 3b. Copy bundled screen-reader DLLs (x64) ---
# Casing matters: lowercase 'n' in nvdaControllerClient64.dll, capital 'T' in Tolk.dll -
# Tolk loads its NVDA client by that exact name at runtime.
foreach ($d in @('Tolk.dll','nvdaControllerClient64.dll')) {
  $src = Join-Path $root (Join-Path 'redist' $d)
  if (Test-Path $src) {
    Copy-Item $src (Join-Path $payload $d) -Force
    Write-Host "Copied $d"
  } else {
    Write-Warning "$d not found in redist\ - patch will fall back to Web Speech until it's present."
  }
}

# --- 4. Shipped readme, generated from ReadMe.md ---
# ReadMe.md is the only readme that is ever committed. The plain-text copy is build output:
# it is generated into obj\ every build, embedded in the installer and shipped in the zip,
# so it can never fall behind the master and never needs hand-editing.
$readme = Join-Path $obj 'ReadMe.txt'
& (Join-Path $root 'tools\readme-to-txt.ps1') -Source (Join-Path $root 'ReadMe.md') -Dest $readme
if (-not (Test-Path $readme)) { throw "Readme generation produced nothing: $readme" }

# --- 5. Compile the installer executable ---
#
# Built with the C# compiler that ships in the box with .NET Framework, so there is no
# build-time dependency to install. That compiler is C# 5 only - installer\BMAInstaller.cs
# is written to that level on purpose.
$csc = Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
if (-not (Test-Path $csc)) { throw "csc.exe not found at $csc - is .NET Framework 4.x present?" }

# Compile into obj\ first and only replace dist\ship\ once it succeeds. Clearing the
# output folder up front means one compile error deletes the last good installer, which
# is exactly what you do not want the moment before handing a build to testers.
$exeName = "BlackmoonProphecy-Accessibility-V$Version-Setup.exe"
$exeStaged = Join-Path $obj $exeName

# Stamp the version into a generated source file (csc has no string-define switch).
$buildInfo = Join-Path $obj 'BuildInfo.cs'
Set-Content -Path $buildInfo -Encoding utf8 -Value @"
// Generated by build.ps1. Do not edit.
namespace BMA { internal static class BuildInfo { internal const string Version = "$Version"; } }
"@

# Embed every payload file as "payload/<relative path>". BMAInstaller.cs enumerates these
# at run time, so adding a file to the payload needs no code change on either side.
$resLines = @()
foreach ($f in Get-ChildItem $payload -Recurse -File) {
  $rel = $f.FullName.Substring($payload.Length + 1).Replace('\','/')
  $resLines += "/resource:`"$($f.FullName)`",payload/$rel"
}
if ($resLines.Count -eq 0) { throw "No payload files to embed - did steps 1-3 run?" }
$resLines += "/resource:`"$readme`",ReadMe.txt"

# A response file sidesteps every quoting question around paths and the comma in /resource.
$rsp = Join-Path $obj 'csc.rsp'
$rspLines = @(
  '/nologo'
  '/target:winexe'
  '/platform:anycpu'
  '/optimize+'
  '/warnaserror-'
  "/out:`"$exeStaged`""
  "/win32manifest:`"$(Join-Path $root 'installer\app.manifest')`""
  '/reference:System.dll'
  '/reference:System.Core.dll'
  '/reference:System.Drawing.dll'
  '/reference:System.Windows.Forms.dll'
) + $resLines + @(
  "`"$(Join-Path $root 'installer\BMAInstaller.cs')`""
  "`"$buildInfo`""
)
Set-Content -Path $rsp -Value $rspLines -Encoding utf8

& $csc "@$rsp"
if ($LASTEXITCODE -ne 0) { throw "Installer compile failed (csc exit $LASTEXITCODE). See the errors above. dist\ship\ was left untouched." }

# Compile succeeded, so it is now safe to rebuild the ship folder.
Remove-Item $ship -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force -Path $ship | Out-Null
$exePath = Join-Path $ship $exeName
Copy-Item $exeStaged $exePath -Force
Copy-Item $readme (Join-Path $ship 'ReadMe.txt') -Force
Write-Host "Compiled -> $exePath"

# --- 6. Stage the manual-install tree beside the installer ---
#
# Laid out as it lands in the game folder, so its contents drop straight into the game
# root and the only remaining step is the plugins.js edit the readme documents.
New-Item -ItemType Directory -Force -Path $shipManual | Out-Null

foreach ($f in Get-ChildItem $payload -Recurse -File) {
  $rel = $f.FullName.Substring($payload.Length + 1)
  # Same split the installer uses: the plugin script goes to www\js\plugins\,
  # everything else under www\mod\.
  $dest = if ($rel -ieq 'BMA_Accessibility.js') {
    Join-Path $shipManual 'www\js\plugins\BMA_Accessibility.js'
  } else {
    Join-Path $shipManual (Join-Path 'www\mod' $rel)
  }
  New-Item -ItemType Directory -Force -Path (Split-Path $dest -Parent) | Out-Null
  Copy-Item $f.FullName $dest -Force
}
Write-Host "Staged manual tree -> $shipManual"

# --- 7. Clear out the retired script-based installer, if a previous build left it ---
foreach ($stale in @('install.bat','install.ps1','uninstall.bat','uninstall.ps1')) {
  Remove-Item (Join-Path $dist $stale) -Force -ErrorAction SilentlyContinue
}

Write-Host ""
Write-Host "Build complete (version $Version)."
Write-Host "  Zip the CONTENTS of: $ship"
Write-Host "  Installer          : $exeName"
